    /**
     * Helper: adds a tablet-making preset to an existing teleport spell's preset list.
     * Also ensures the spell has presets even if none existed before.
     */
    private static void registerTabletSpell(String spellName, int tabletItemId)
    {
        ConversionPreset preset = new ConversionPreset(
            "Tablet (at lectern)", tabletItemId,
            "Tablet", 1, 0,
            input(ItemID.SOFT_CLAY, "Soft clay", 1)
        );

        List<ConversionPreset> existing = PRESETS.get(spellName);
        if (existing == null)
        {
            PRESETS.put(spellName, new ArrayList<>(Collections.singletonList(preset)));
        }
        else
        {
            List<ConversionPreset> mutable = new ArrayList<>(existing);
            mutable.add(preset);
            PRESETS.put(spellName, mutable);
        }
    }

    public static List<ConversionPreset> getPresetsForSpell(String spellName)
    {
        return PRESETS.get(spellName);
    }

    public static Map<String, List<ConversionPreset>> getAllPresets()
    {
        return PRESETS;
    }

    public static boolean hasPresets(String spellName)
    {
        return PRESETS.containsKey(spellName);
    }
}

package com.castcalc;

import java.util.Arrays;
import java.util.List;

public class SpellData
{
    private final String name;
    private final Spellbook spellbook;
    private final SpellCategory category;
    private final int levelRequired;
    private final boolean hasProfitLoss;
    private final double xpPerCast;
    private final XpMode xpMode;
    private final List<RuneRequirement> runeRequirements;

    public SpellData(String name, Spellbook spellbook, SpellCategory category,
                     int levelRequired, boolean hasProfitLoss,
                     double xpPerCast, XpMode xpMode,
                     RuneRequirement... requirements)
    {
        this.name = name;
        this.spellbook = spellbook;
        this.category = category;
        this.levelRequired = levelRequired;
        this.hasProfitLoss = hasProfitLoss;
        this.xpPerCast = xpPerCast;
        this.xpMode = xpMode;
        this.runeRequirements = Arrays.asList(requirements);
    }

    public String getName() { return name; }
    public Spellbook getSpellbook() { return spellbook; }
    public SpellCategory getCategory() { return category; }
    public int getLevelRequired() { return levelRequired; }
    public boolean hasProfitLoss() { return hasProfitLoss; }
    public double getXpPerCast() { return xpPerCast; }
    public XpMode getXpMode() { return xpMode; }
    public List<RuneRequirement> getRuneRequirements() { return runeRequirements; }

    @Override
    public String toString() { return name; }
}

