package com.castcalc;

/**
 * Describes how a spell's Magic XP should be treated in the level calculator.
 *
 * NORMAL   - Has a clear fixed XP value. Fully calculable in all three modes.
 * COMBAT   - Combat spell. XP per cast is variable in practice (splash vs hit).
 *            Muted in Level mode with "Combat spell" label.
 * REANIMATE - Gives a small amount of Magic XP but not a practical training method.
 *            Muted in Level mode with "Negligible XP" label.
 * VARIES   - XP changes depending on context (e.g. Enchant Crossbow Bolt by bolt type).
 *            Muted in Level mode with "XP varies" label.
 */
public enum XpMode
{
    NORMAL,
    COMBAT,
    REANIMATE,
    VARIES;

    /** Whether this spell is fully calculable in Level mode. */
    public boolean isCalculable()
    {
        return this == NORMAL;
    }

    /**
     * Short label shown in Level mode for non-calculable spells.
     * Returns null for NORMAL (no label needed).
     */
    public String getMutedLabel()
    {
        switch (this)
        {
            case COMBAT:    return "Combat spell";
            case REANIMATE: return "Negligible Magic XP";
            case VARIES:    return "XP varies";
            default:        return null;
        }
    }
}

package com.castcalc;

import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Calculates the GP cost of casting a spell, factoring in equipped
 * rune-saving gear and live GE rune prices.
 *
 * Prices are cached via refreshPriceCache() which should be called from
 * the client thread. The panel (Swing thread) reads from this cache.
 */
public class CostCalculator
{
    private final Client client;
    private final ItemManager itemManager;

    // Thread-safe price cache, populated on the client thread
    private final Map<Integer, Integer> priceCache = new ConcurrentHashMap<>();

    public CostCalculator(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;
    }

    /**
     * Refreshes the price cache. MUST be called from the client thread.
     * Caches rune prices and any items referenced in ConversionPresets.
     */
    public void refreshPriceCache()
    {
        // Cache all rune prices
        for (Rune rune : Rune.values())
        {
            try
            {
                priceCache.put(rune.getItemId(), itemManager.getItemPrice(rune.getItemId()));
            }
            catch (Exception e)
            {
                priceCache.put(rune.getItemId(), 0);
            }
        }

        // Cache prices for all items referenced in conversion presets
        for (Map.Entry<String, java.util.List<ConversionPreset>> entry : ConversionPreset.getAllPresets().entrySet())
        {
            for (ConversionPreset preset : entry.getValue())
            {
                if (preset.getOutputItemId() > 0)
                {
                    try
                    {
                        priceCache.put(preset.getOutputItemId(),
                            itemManager.getItemPrice(preset.getOutputItemId()));
                    }
                    catch (Exception e)
                    {
                        priceCache.put(preset.getOutputItemId(), 0);
                    }
                }
                for (ConversionPreset.ItemInput input : preset.getInputs())
                {
                    try
                    {
                        priceCache.put(input.getItemId(),
                            itemManager.getItemPrice(input.getItemId()));
                    }
                    catch (Exception e)
                    {
                        priceCache.put(input.getItemId(), 0);
                    }
                }
            }
        }
    }

    /**
     * Caches a single item price. Call from client thread.
     * Used on-demand from the alch item search.
     */
    public void cacheItemPrice(int itemId)
    {
        try
        {
            priceCache.put(itemId, itemManager.getItemPrice(itemId));
        }
        catch (Exception e)
        {
            priceCache.put(itemId, 0);
        }
    }

    /**
     * Returns the cached price, or 0 if not cached.
     */
    public int getRunePrice(Rune rune)
    {
        Integer cached = priceCache.get(rune.getItemId());
        return cached != null ? cached : 0;
    }

    public int getItemPrice(int itemId)
    {
        Integer cached = priceCache.get(itemId);
        return cached != null ? cached : 0;
    }

    /**
     * Direct price lookup (unsafe from Swing thread). Used only when caller
     * is already on the client thread (e.g., from within cacheItemPrice flows).
     */
    public ItemManager getItemManager()
    {
        return itemManager;
    }

    public long calculateCastCost(SpellData spell, boolean useGearSave)
    {
        Set<Rune> providedRunes = useGearSave
            ? RuneSavingGear.getCachedProvidedRunes()
            : EnumSet.noneOf(Rune.class);

        long totalCost = 0;

        for (RuneRequirement req : spell.getRuneRequirements())
        {
            if (providedRunes.contains(req.getRune()))
            {
                continue;
            }

            int pricePerRune = getRunePrice(req.getRune());
            double saveChance = useGearSave
                ? RuneSavingGear.getRuneSaveChance(req.getRune())
                : 0.0;

            double effectiveCost = pricePerRune * req.getQuantity() * (1.0 - saveChance);
            totalCost += Math.round(effectiveCost);
        }

        return totalCost;
    }

    public Map<String, Long> getCostBreakdown(SpellData spell, boolean useGearSave)
    {
        Set<Rune> providedRunes = useGearSave
            ? RuneSavingGear.getCachedProvidedRunes()
            : EnumSet.noneOf(Rune.class);

        Map<String, Long> breakdown = new LinkedHashMap<>();

        for (RuneRequirement req : spell.getRuneRequirements())
        {
            String label = req.getQuantity() + "x " + req.getRune().getName() + " rune";

            if (providedRunes.contains(req.getRune()))
            {
                breakdown.put(label + " (free)", 0L);
                continue;
            }

            int pricePerRune = getRunePrice(req.getRune());
            double saveChance = useGearSave
                ? RuneSavingGear.getRuneSaveChance(req.getRune())
                : 0.0;

            long cost = Math.round(pricePerRune * req.getQuantity() * (1.0 - saveChance));
            if (saveChance > 0)
            {
                label += String.format(" (%.1f%% save)", saveChance * 100);
            }
            breakdown.put(label, cost);
        }

        return breakdown;
    }

    /**
     * Structured version of the rune cost breakdown, used to render icon +
     * name + quantity + cost line items in the UI. Prefer this over
     * getCostBreakdown() (which returns pre-formatted label strings) for
     * any new rendering code.
     */
    public List<RuneLineItem> getRuneLineItems(SpellData spell, boolean useGearSave)
    {
        Set<Rune> providedRunes = useGearSave
            ? RuneSavingGear.getCachedProvidedRunes()
            : EnumSet.noneOf(Rune.class);

        List<RuneLineItem> items = new java.util.ArrayList<>();

        for (RuneRequirement req : spell.getRuneRequirements())
        {
            if (providedRunes.contains(req.getRune()))
            {
                items.add(new RuneLineItem(req.getRune(), req.getQuantity(), 0L, true, 0.0));
                continue;
            }

            int pricePerRune = getRunePrice(req.getRune());
            double saveChance = useGearSave
                ? RuneSavingGear.getRuneSaveChance(req.getRune())
                : 0.0;
            long cost = Math.round(pricePerRune * req.getQuantity() * (1.0 - saveChance));

            items.add(new RuneLineItem(req.getRune(), req.getQuantity(), cost, false, saveChance));
        }

        return items;
    }

    /** One line item in a rune cost breakdown: which rune, how many, what it costs. */
    public static class RuneLineItem
    {
        public final Rune rune;
        public final int quantity;
        public final long cost;
        public final boolean free;
        public final double savePercent; // 0 if no rune-saving gear applies

        public RuneLineItem(Rune rune, int quantity, long cost, boolean free, double savePercent)
        {
            this.rune = rune;
            this.quantity = quantity;
            this.cost = cost;
            this.free = free;
            this.savePercent = savePercent;
        }
    }

    public PresetResult calculatePresetProfit(SpellData spell, ConversionPreset preset,
                                              boolean useGear)
    {
        long totalInputCost = 0;
        for (ConversionPreset.ItemInput input : preset.getInputs())
        {
            totalInputCost += (long) getItemPrice(input.getItemId()) * input.getQuantity();
        }

        long outputValue = 0;
        boolean isXpOnly = preset.getOutputItemId() == -1;
        if (!isXpOnly)
        {
            outputValue = (long) getItemPrice(preset.getOutputItemId()) * preset.getOutputQty();
        }

        long runeCost = calculateCastCost(spell, useGear);
        long profit = outputValue - totalInputCost - runeCost - preset.getExtraGpCost();

        return new PresetResult(totalInputCost, outputValue, runeCost,
            preset.getExtraGpCost(), profit, isXpOnly);
    }

    public static class PresetResult
    {
        public final long inputCost;
        public final long outputValue;
        public final long runeCost;
        public final long extraFee;
        public final long profit;
        public final boolean isXpOnly;

        public PresetResult(long inputCost, long outputValue, long runeCost,
                            long extraFee, long profit, boolean isXpOnly)
        {
            this.inputCost = inputCost;
            this.outputValue = outputValue;
            this.runeCost = runeCost;
            this.extraFee = extraFee;
            this.profit = profit;
            this.isXpOnly = isXpOnly;
        }

        public long totalCost()
        {
            return inputCost + runeCost + extraFee;
        }
    }
}

package com.castcalc;

import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;

import java.util.*;

/**
 * Detects equipped rune-saving gear and calculates which runes
 * are provided for free or have a chance to be saved.
 *
 * IMPORTANT: All methods that access the Client must be called
 * from the client thread (e.g., from event subscribers).
 * Use the cached version (getCachedProvidedRunes) from the Swing thread.
 */
public class RuneSavingGear
{
    // Map of weapon/shield item IDs -> set of rune types they provide for free
    private static final Map<Integer, Set<Rune>> ELEMENTAL_PROVIDERS = new HashMap<>();

    // Items that give a % chance to save runes
    public static final int BRYOPHYTAS_STAFF = ItemID.BRYOPHYTAS_STAFF;
    public static final int KODAI_WAND = ItemID.KODAI_WAND;

    // Tome of fire provides fire runes when equipped in shield slot
    public static final int TOME_OF_FIRE = ItemID.TOME_OF_FIRE;
    public static final int TOME_OF_WATER = ItemID.TOME_OF_WATER;

    // Cached state — updated from client thread, read from Swing thread
    private static Set<Rune> cachedProvidedRunes = EnumSet.noneOf(Rune.class);
    private static List<String> cachedEffects = new ArrayList<>();
    private static int cachedWeaponId = -1;

    static
    {
        // --- Air ---
        Set<Rune> air = EnumSet.of(Rune.AIR);
        ELEMENTAL_PROVIDERS.put(ItemID.STAFF_OF_AIR, air);
        ELEMENTAL_PROVIDERS.put(ItemID.AIR_BATTLESTAFF, air);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_AIR_STAFF, air);

        // --- Water ---
        Set<Rune> water = EnumSet.of(Rune.WATER);
        ELEMENTAL_PROVIDERS.put(ItemID.STAFF_OF_WATER, water);
        ELEMENTAL_PROVIDERS.put(ItemID.WATER_BATTLESTAFF, water);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_WATER_STAFF, water);

        // --- Earth ---
        Set<Rune> earth = EnumSet.of(Rune.EARTH);
        ELEMENTAL_PROVIDERS.put(ItemID.STAFF_OF_EARTH, earth);
        ELEMENTAL_PROVIDERS.put(ItemID.EARTH_BATTLESTAFF, earth);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_EARTH_STAFF, earth);

        // --- Fire ---
        Set<Rune> fire = EnumSet.of(Rune.FIRE);
        ELEMENTAL_PROVIDERS.put(ItemID.STAFF_OF_FIRE, fire);
        ELEMENTAL_PROVIDERS.put(ItemID.FIRE_BATTLESTAFF, fire);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_FIRE_STAFF, fire);

        // --- Combination staves ---
        Set<Rune> steamRunes = EnumSet.of(Rune.WATER, Rune.FIRE);
        ELEMENTAL_PROVIDERS.put(ItemID.STEAM_BATTLESTAFF, steamRunes);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_STEAM_STAFF, steamRunes);

        Set<Rune> smokeRunes = EnumSet.of(Rune.AIR, Rune.FIRE);
        ELEMENTAL_PROVIDERS.put(ItemID.SMOKE_BATTLESTAFF, smokeRunes);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_SMOKE_STAFF, smokeRunes);

        Set<Rune> dustRunes = EnumSet.of(Rune.AIR, Rune.EARTH);
        ELEMENTAL_PROVIDERS.put(ItemID.DUST_BATTLESTAFF, dustRunes);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_DUST_STAFF, dustRunes);

        Set<Rune> mudRunes = EnumSet.of(Rune.WATER, Rune.EARTH);
        ELEMENTAL_PROVIDERS.put(ItemID.MUD_BATTLESTAFF, mudRunes);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_MUD_STAFF, mudRunes);

        Set<Rune> lavaRunes = EnumSet.of(Rune.FIRE, Rune.EARTH);
        ELEMENTAL_PROVIDERS.put(ItemID.LAVA_BATTLESTAFF, lavaRunes);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_LAVA_STAFF, lavaRunes);

        Set<Rune> mistRunes = EnumSet.of(Rune.WATER, Rune.AIR);
        ELEMENTAL_PROVIDERS.put(ItemID.MIST_BATTLESTAFF, mistRunes);
        ELEMENTAL_PROVIDERS.put(ItemID.MYSTIC_MIST_STAFF, mistRunes);

        // Kodai wand provides water runes (and has 15% rune save)
        Set<Rune> kodaiRunes = EnumSet.of(Rune.WATER);
        ELEMENTAL_PROVIDERS.put(ItemID.KODAI_WAND, kodaiRunes);
    }

    /**
     * Update the cached gear state. MUST be called from the client thread
     * (e.g., from an event subscriber like onItemContainerChanged).
     */
    public static void updateCache(Client client)
    {
        Set<Rune> provided = EnumSet.noneOf(Rune.class);
        List<String> effects = new ArrayList<>();
        int weaponId = -1;

        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);

        if (equipment != null)
        {
            Item[] items = equipment.getItems();

            // Check weapon slot
            if (items.length > EquipmentInventorySlot.WEAPON.getSlotIdx())
            {
                weaponId = items[EquipmentInventorySlot.WEAPON.getSlotIdx()].getId();
                Set<Rune> weaponRunes = ELEMENTAL_PROVIDERS.get(weaponId);
                if (weaponRunes != null)
                {
                    provided.addAll(weaponRunes);
                }
            }

            // Check shield slot (Tome of Fire / Tome of Water)
            if (items.length > EquipmentInventorySlot.SHIELD.getSlotIdx())
            {
                int shieldId = items[EquipmentInventorySlot.SHIELD.getSlotIdx()].getId();
                if (shieldId == TOME_OF_FIRE)
                {
                    provided.add(Rune.FIRE);
                }
                else if (shieldId == TOME_OF_WATER)
                {
                    provided.add(Rune.WATER);
                }
            }
        }

        // Build effects list
        if (!provided.isEmpty())
        {
            StringBuilder sb = new StringBuilder("Free runes: ");
            boolean first = true;
            for (Rune r : provided)
            {
                if (!first) sb.append(", ");
                sb.append(r.getName());
                first = false;
            }
            effects.add(sb.toString());
        }

        if (weaponId == KODAI_WAND)
        {
            effects.add("Kodai wand: 15% rune save");
        }
        if (weaponId == BRYOPHYTAS_STAFF)
        {
            effects.add("Bryophyta's staff: 1/15 nature rune save");
        }

        // Store in cache (thread-safe enough for our purposes)
        cachedProvidedRunes = provided;
        cachedEffects = effects;
        cachedWeaponId = weaponId;
    }

    /**
     * Returns cached provided runes. Safe to call from any thread.
     */
    public static Set<Rune> getCachedProvidedRunes()
    {
        return cachedProvidedRunes;
    }

    /**
     * Returns cached active effects list. Safe to call from any thread.
     */
    public static List<String> getCachedEffects()
    {
        return cachedEffects;
    }

    /**
     * Returns the rune-saving probability from cached gear state.
     * Safe to call from any thread.
     */
    public static double getRuneSaveChance(Rune rune)
    {
        // Kodai wand: 15% chance to save all runes
        if (cachedWeaponId == KODAI_WAND)
        {
            return 0.15;
        }

        // Bryophyta's staff: 1/15 chance to save nature runes only
        if (cachedWeaponId == BRYOPHYTAS_STAFF && rune == Rune.NATURE)
        {
            return 1.0 / 15.0;
        }

        return 0.0;
    }
}

package com.castcalc;

/**
 * Precomputed OSRS XP table for levels 1-99.
 *
 * Formula: XP(n) = floor(1/4 * sum(i=1 to n-1, floor(i + 300 * 2^(i/7))))
 * Source: OSRS Wiki - https://oldschool.runescape.wiki/w/Experience
 *
 * Used by the level calculator to convert between levels and XP values.
 */
public final class MagicXpTable
{
    private MagicXpTable() {}

    /** XP_TABLE[level] = total XP required to reach that level. Index 1 = 0 XP. */
    private static final long[] XP_TABLE = new long[100];

    static
    {
        XP_TABLE[1] = 0;
        for (int level = 2; level <= 99; level++)
        {
            long points = 0;
            for (int i = 1; i < level; i++)
            {
                points += (long) Math.floor(i + 300.0 * Math.pow(2.0, i / 7.0));
            }
            XP_TABLE[level] = points / 4;
        }
    }

    /** XP required to reach the given level (clamped to 1-99). */
    public static long xpForLevel(int level)
    {
        if (level <= 1) return 0;
        if (level >= 99) return XP_TABLE[99];
        return XP_TABLE[level];
    }

    /** Current level at the given cumulative XP total. */
    public static int levelForXp(long xp)
    {
        if (xp <= 0) return 1;
        for (int level = 99; level >= 2; level--)
        {
            if (xp >= XP_TABLE[level]) return level;
        }
        return 1;
    }

    /** Formats an XP value as a short string (e.g. 737,627 -> "737.6K"). */
    public static String formatXp(long xp)
    {
        if (xp >= 1_000_000) return String.format("%.1fM", xp / 1_000_000.0);
        if (xp >= 1_000)     return String.format("%.1fK", xp / 1_000.0);
        return String.valueOf(xp);
    }
}
